-- ExamFlow institution server: database schema for IBM Db2 11.5+
-- Schema version 2. Run it connected to the EMPTY database (or schema) made for ExamFlow,
-- as its owner or an admin. Safe to run twice. Then give the ExamFlow user the rights listed in DATABASES.md.

-- Run with the Db2 command line, "@" ends each statement:  db2 connect to EXAMFLOW && db2 -td@ -vf db2.sql

-- ── step 1 ──
BEGIN DECLARE CONTINUE HANDLER FOR SQLSTATE '42710' BEGIN END; EXECUTE IMMEDIATE 'CREATE TABLE "meta" ("k" VARCHAR(191) NOT NULL, "v" CLOB(1G), PRIMARY KEY ("k"))'; END @
BEGIN DECLARE CONTINUE HANDLER FOR SQLSTATE '42710' BEGIN END; EXECUTE IMMEDIATE 'CREATE TABLE "docs" ("col" VARCHAR(64) NOT NULL, "id" VARCHAR(300) NOT NULL, "data" CLOB(1G) NOT NULL, "created" BIGINT NOT NULL, "updated" BIGINT NOT NULL, f_examToken VARCHAR(255), f_teacherUid VARCHAR(255), f_switchCode VARCHAR(255), PRIMARY KEY ("col", "id"))'; END @
BEGIN DECLARE CONTINUE HANDLER FOR SQLSTATE '42710' BEGIN END; EXECUTE IMMEDIATE 'CREATE TABLE "users" ("uid" VARCHAR(191) NOT NULL, "email" VARCHAR(320) NOT NULL, "name" VARCHAR(800), "pass_hash" VARCHAR(800), "source" VARCHAR(32) NOT NULL, "oidc_sub" VARCHAR(800), "created" BIGINT NOT NULL, "disabled" INTEGER DEFAULT 0 NOT NULL, PRIMARY KEY ("uid"), UNIQUE ("email"))'; END @
BEGIN DECLARE CONTINUE HANDLER FOR SQLSTATE '42710' BEGIN END; EXECUTE IMMEDIATE 'CREATE TABLE "codes" ("code_hash" VARCHAR(191) NOT NULL, "email" VARCHAR(800) NOT NULL, "purpose" VARCHAR(32) NOT NULL, "created" BIGINT NOT NULL, "expires" BIGINT NOT NULL, "used" BIGINT, PRIMARY KEY ("code_hash"))'; END @
BEGIN DECLARE CONTINUE HANDLER FOR SQLSTATE '42710' BEGIN END; EXECUTE IMMEDIATE 'CREATE TABLE "logins" ("token_hash" VARCHAR(191) NOT NULL, "uid" VARCHAR(191) NOT NULL, "created" BIGINT NOT NULL, "expires" BIGINT NOT NULL, PRIMARY KEY ("token_hash"))'; END @
BEGIN DECLARE CONTINUE HANDLER FOR SQLSTATE '42710' BEGIN END; EXECUTE IMMEDIATE 'CREATE TABLE "oidc_state" ("state" VARCHAR(191) NOT NULL, "nonce" VARCHAR(800) NOT NULL, "verifier" VARCHAR(800) NOT NULL, "created" BIGINT NOT NULL, PRIMARY KEY ("state"))'; END @
BEGIN DECLARE CONTINUE HANDLER FOR SQLSTATE '42710' BEGIN END; EXECUTE IMMEDIATE 'CREATE TABLE "allowlist" ("teacher_id" VARCHAR(191) NOT NULL, "email" VARCHAR(320) NOT NULL, "name" VARCHAR(800), "version" INTEGER NOT NULL, PRIMARY KEY ("teacher_id"), UNIQUE ("email"))'; END @
BEGIN DECLARE CONTINUE HANDLER FOR SQLSTATE '42710' BEGIN END; EXECUTE IMMEDIATE 'CREATE TABLE "allowlist_history" ("n" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY, "t" BIGINT NOT NULL, "package_id" VARCHAR(800), "package_version" VARCHAR(800), "list_version" INTEGER, "added" INTEGER, "removed" INTEGER, "total" INTEGER, PRIMARY KEY ("n"))'; END @
BEGIN DECLARE CONTINUE HANDLER FOR SQLSTATE '42710' BEGIN END; EXECUTE IMMEDIATE 'CREATE TABLE "audit" ("n" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY, "t" BIGINT NOT NULL, "actor" VARCHAR(800), "action" VARCHAR(800) NOT NULL, "target" CLOB(1G), "result" VARCHAR(800) NOT NULL, "detail" CLOB(1G), PRIMARY KEY ("n"))'; END @
BEGIN DECLARE CONTINUE HANDLER FOR SQLSTATE '42710' BEGIN END; EXECUTE IMMEDIATE 'CREATE INDEX docs_examToken ON "docs" ("col", f_examToken)'; END @
BEGIN DECLARE CONTINUE HANDLER FOR SQLSTATE '42710' BEGIN END; EXECUTE IMMEDIATE 'CREATE INDEX docs_teacherUid ON "docs" ("col", f_teacherUid)'; END @
BEGIN DECLARE CONTINUE HANDLER FOR SQLSTATE '42710' BEGIN END; EXECUTE IMMEDIATE 'CREATE INDEX docs_switchCode ON "docs" ("col", f_switchCode)'; END @
BEGIN DECLARE CONTINUE HANDLER FOR SQLSTATE '42710' BEGIN END; EXECUTE IMMEDIATE 'CREATE INDEX docs_created ON "docs" ("col", "created")'; END @
-- append-only protection for the audit log (audit_no_update)
CREATE OR REPLACE TRIGGER audit_no_update NO CASCADE BEFORE UPDATE ON "audit" FOR EACH ROW SIGNAL SQLSTATE '75001' SET MESSAGE_TEXT = 'the audit log is append-only' @
-- append-only protection for the audit log (audit_no_delete)
CREATE OR REPLACE TRIGGER audit_no_delete NO CASCADE BEFORE DELETE ON "audit" FOR EACH ROW SIGNAL SQLSTATE '75001' SET MESSAGE_TEXT = 'the audit log is append-only' @

-- ── step 2 ──
BEGIN DECLARE CONTINUE HANDLER FOR SQLSTATE '42710' BEGIN END; EXECUTE IMMEDIATE 'CREATE TABLE "inbox" ("msg_id" VARCHAR(64) NOT NULL, "email" VARCHAR(254) NOT NULL, "delivered_at" BIGINT, "read_at" BIGINT, "archived_at" BIGINT, PRIMARY KEY ("msg_id", "email"))'; END @

-- record which schema version this database has
MERGE INTO "meta" "t" USING (VALUES (CAST('schema_version' AS VARCHAR(191)), CAST('2' AS CLOB(1G)))) s ("k", "v") ON "t"."k" = s."k" WHEN MATCHED THEN UPDATE SET "v" = s."v" WHEN NOT MATCHED THEN INSERT ("k", "v") VALUES (s."k", s."v") @

COMMIT @
